### Java

```java
import java.util.Scanner;

public class Main {

    // 判断当前像素画是否优美
    public static boolean isBeautiful(int n, int m, String[] grid) {
        // 长和宽必须都是偶数
        if (n % 2 != 0 || m % 2 != 0) {
            return false;
        }

        // 枚举所有 2x2 子矩阵
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < m - 1; j++) {
                // 判断四个位置是否都是 '1'
                if (grid[i].charAt(j) == '1' &&
                    grid[i].charAt(j + 1) == '1' &&
                    grid[i + 1].charAt(j) == '1' &&
                    grid[i + 1].charAt(j + 1) == '1') {
                    return true;
                }
            }
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 输入测试组数
        int T = sc.nextInt();

        while (T-- > 0) {
            // 输入长和宽
            int n = sc.nextInt();
            int m = sc.nextInt();

            // 输入像素画
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next();
            }

            // 输出结果
            if (isBeautiful(n, m, grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }

        sc.close();
    }
}
